package com.amar.slackclone.search;import com.amar.slackclone.search.dto.SearchResponse;import com.amar.slackclone.search.dto.SearchResponse.*;import com.amar.slackclone.channel.*;import com.amar.slackclone.message.*;import com.amar.slackclone.conversation.*;import com.amar.slackclone.workspace.*;import com.amar.slackclone.user.*;import org.springframework.data.domain.PageRequest;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/search") public class SearchController{private final UserRepository users;private final WorkspaceMemberRepository wm;private final ChannelRepository channels;private final MessageRepository messages;private final ConversationMessageRepository conversationMessages;private final ConversationService conversations;public SearchController(UserRepository u,WorkspaceMemberRepository w,ChannelRepository c,MessageRepository m,ConversationMessageRepository cm,ConversationService cs){users=u;wm=w;channels=c;messages=m;conversationMessages=cm;conversations=cs;}
@GetMapping @Transactional(readOnly=true) public SearchResponse search(@RequestParam String q,@RequestParam(required=false)Long workspaceId,Authentication a){String term=q.trim();if(term.length()<2)return new SearchResponse(List.of(),List.of(),List.of(),List.of());User me=users.findByEmailIgnoreCase(a.getName()).orElseThrow();var workspaces=wm.findAllByUserId(me.getId());Set<Long>wids=new HashSet<>(workspaces.stream().map(x->x.getWorkspace().getId()).toList());if(workspaceId!=null)wids.retainAll(Set.of(workspaceId));List<Channel> visible=wids.stream().flatMap(id->channels.findVisibleChannels(id,me.getId()).stream()).toList();Set<Long>cids=new HashSet<>(visible.stream().map(Channel::getId).toList());List<MessageResult> results=cids.isEmpty()?List.of():messages.searchAccessible(cids,term,PageRequest.of(0,30)).stream().map(m->new MessageResult(m.getId(),snippet(m.getContent()),m.getSender().getDisplayName(),m.getCreatedAt(),"CHANNEL",m.getChannel().getWorkspace().getId(),m.getChannel().getId(),m.getChannel().getName())).toList();List<MessageResult> dm=conversationMessages.searchAccessible(me.getId(),term,PageRequest.of(0,30)).stream().map(m->new MessageResult(m.getId(),snippet(m.getContent()),m.getSender().getDisplayName(),m.getCreatedAt(),m.getConversation().getType().name(),null,m.getConversation().getId(),"Conversation")).toList();var all=new ArrayList<>(results);all.addAll(dm);var channelResults=visible.stream().filter(c->c.getName().toLowerCase().contains(term.toLowerCase())).map(c->new ContextResult(c.getId(),c.getName(),"CHANNEL",c.getWorkspace().getId())).limit(20).toList();var people=wm.findMessageableUsers(me.getId()).stream().filter(u->u.getDisplayName().toLowerCase().contains(term.toLowerCase())||u.getEmail().toLowerCase().contains(term.toLowerCase())).map(u->new UserResult(u.getId(),u.getDisplayName(),u.getEmail())).limit(20).toList();var conv=conversations.list(a.getName()).stream().filter(c->c.displayName().toLowerCase().contains(term.toLowerCase())).map(c->new ContextResult(c.id(),c.displayName(),c.type().name(),null)).limit(20).toList();return new SearchResponse(all,channelResults,people,conv);}private String snippet(String s){return s.length()>180?s.substring(0,180)+"…":s;}}
